declare(strict_types=1);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#101827"><link rel="stylesheet" href="assets/style.css"><title>REALWIN Dashboard</title></head><body><header class="topbar"><a class="brand" href="index.php"><span class="brand-mark">R</span><span>REAL<span class="accent">WIN</span><small>PLAYER SPACE</small></span></a><div class="top-actions"><a class="btn btn-outline" href="admin.php">Admin</a><button class="btn btn-outline" id="logout">Log out</button></div></header><main class="wrap section"><span class="eyebrow">YOUR PLAYER SPACE</span><h1>Welcome, <em id="playerName">player</em></h1><div class="game-grid"><article class="game-card"><span class="game-type">YOUR ENTERTAINMENT SCORE</span><h2 id="points">0</h2><p>Points have no cash value and cannot be transferred or redeemed.</p></article><article class="game-card game-blue"><span class="game-type">ACCOUNT</span><h3 id="email">Loading…</h3><p id="uid"></p></article><article class="game-card game-orange"><span class="game-type">PLAY SAFE</span><h3>No cash stakes</h3><p>Only approved social entertainment games are available.</p></article></div><section class="section"><h2>Game activity</h2><div class="panel"><p id="history">Your recent score activity will appear here after the API is connected.</p></div></section></main><script>
const API='/backend/api';const token=sessionStorage.getItem('rw_token');if(!token)location.href='index.php';async function go(){try{const r=await fetch(API+'/auth/me.php',{headers:{Authorization:'Bearer '+token}});const d=await r.json();if(!r.ok||!d.ok)throw Error();document.getElementById('playerName').textContent=d.user.username;document.getElementById('email').textContent=d.user.email;document.getElementById('uid').textContent='UID: '+d.user.id;document.getElementById('points').textContent=Number(d.points).toLocaleString();const h=await fetch(API+'/points/history.php',{headers:{Authorization:'Bearer '+token}});const hd=await h.json();if(hd.ok&&hd.history.length)document.getElementById('history').innerHTML=hd.history.map(x=>'<p>'+String(x.description).replace(/[<>]/g,'')+' · '+(x.amount>0?'+':'')+x.amount+' points</p>').join('')}catch{sessionStorage.removeItem('rw_token');location.href='index.php'}}document.getElementById('logout').onclick=async()=>{try{await fetch(API+'/auth/logout.php',{method:'POST',headers:{Authorization:'Bearer '+token}})}catch{}sessionStorage.removeItem('rw_token');location.href='index.php'};go();
</script></body></html>